files.content:
.page {
  margin: 0;
  font-family: Helvetica, Arial, sans-serif;
  background: #000;
}

.header {
  display: flex;
  align-items: center;
  min-height: 80px;
  padding: 0 60px;
}

.header img {
  width: 200px;
}

.gallery {
  display: grid;
  grid-template-columns: repeat(4, 1fr) 2fr 200px;
  grid-template-rows: repeat(6, 1fr);
  gap: 10px;
  box-sizing: border-box;
  min-height: calc(100vh - 80px);
  padding: 0 60px 60px;
}

.gallery__item {
  box-sizing: border-box;
  margin: 0;
}

.gallery__image {
  width: 100%;
  height: 100%;
  max-height: 100%;
  object-fit: cover;
}

.gallery__item:nth-child(7) {
  grid-column: 6 / -1;
  grid-row: 1 / -1;
}

.gallery__item:nth-child(5) {
  grid-column: 4 / 6;
  grid-row: 4 / -1;
}

.gallery__item:nth-child(1) {
  grid-column: span 2;
  grid-row: span 2;
}

.gallery__item:nth-child(3) {
  grid-column: span 2;
  grid-row: span 2;
}

.gallery__item:nth-child(2) {
  grid-column: 3 / 6;
  grid-row: span 3;
}

.gallery__item:nth-child(4) {
  grid-column: 1 / 4;
  grid-row: span 2;
}

.gallery__item:nth-child(6) {
  grid-column: 3;
  grid-row: 4;

}
